// ============================================================================
// IMPORTS
// ============================================================================

// React core hooks
import { useState, useEffect, useRef } from "react";
// UI Components

import LandingPage from "./components/LandingPage";
import Header from "./components/Header";
import ToastContainer from "./components/ToastContainer";
import GlobalModals from "./components/GlobalModals";
import MainLayout from "./components/MainLayout";
import CrashRecoveryPrompt from "./components/CrashRecoveryPrompt";
import Footer from "./components/Footer";
import SignIn from "./components/SignIn";
import InviteSignUp from "./components/InviteSignUp";
import ApiKeyModal from "./components/ApiKeyModal";
import { getInviteFromUrl } from "./services/inviteService";

// Custom Hooks
import { useAppConfig } from "./hooks/useAppConfig";
import { useQuestionManager } from "./hooks/useQuestionManager";
import { useFileHandler } from "./hooks/useFileHandler";
import { useGeneration } from "./hooks/useGeneration";
import { useExport } from "./hooks/useExport";
import { useCrashRecovery } from "./hooks/useCrashRecovery";
import { useTutorial } from "./hooks/useTutorial";
import { useReviewActions } from "./hooks/useReviewActions";
import { useDatabaseActions } from "./hooks/useDatabaseActions";
import { useNavigation } from "./hooks/useNavigation";
import { useFiltering } from "./hooks/useFiltering";
import { useKeyboardShortcuts } from "./hooks/useKeyboardShortcuts";
import { useToast } from "./hooks/useToast";
import { useBulkSelection } from "./hooks/useBulkSelection";
import { useAuth } from "./hooks/useAuth";
import { useModalState } from "./hooks/useModalState";
import { useAppHandlers } from "./hooks/useAppHandlers";
// Utilities

// Simple loading spinner component for auth loading state
const LoadingSpinner = () => (
  <div className="flex items-center justify-center h-screen bg-slate-950">
    <div className="w-12 h-12 border-4 border-cyan-500 border-t-transparent rounded-full animate-spin" />
  </div>
);

const App = () => {
  // ========================================================================
  // HOOKS - Toast Notifications
  // ========================================================================
  const { toasts, addToast: _addToast, removeToast, showMessage } = useToast();

  // ========================================================================
  // HOOKS - Auth, Custom Tags, and Compliance (extracted to useAuth)
  // ========================================================================
  const {
    user,
    authLoading,
    isAdmin,
    isRegistered,
    registrationLoading,
    markAsRegistered,
    customTags,
    setCustomTags: _setCustomTags,
    handleSaveCustomTags,
    tokenUsage,
    showTerms,
    setShowTerms,
    showAgeGate,
    setShowAgeGate,
    termsAccepted: _termsAccepted,
    setTermsAccepted,
  } = useAuth(showMessage);

  // ... (rest of the file)

  // 0. Tutorial System
  const {
    tutorialActive,
    currentStep,
    tutorialSteps,
    handleTutorialNext,
    handleTutorialPrev,
    handleTutorialSkip,
    handleTutorialComplete,
    handleRestartTutorial,
    handleStartTutorial,
  } = useTutorial(showMessage);

  // ========================================================================
  // HOOKS - State Management
  // ========================================================================

  // 1. App Configuration & UI State
  const {
    appMode,
    setAppMode,
    config,
    setConfig,
    isAuthReady,
    isApiReady,
    effectiveApiKey,
    apiKeyStatus,
    showNameModal,
    setShowNameModal,
    showGenSettings,
    setShowGenSettings,
    setShowApiError,
    batchSizeWarning,
    showSettings,
    setShowSettings,
    showApiKey,
    setShowApiKey,
    handleChange,
    handleNameSave,
    handleLanguageSwitch,
  } = useAppConfig();

  // 2. Question Data Management
  const {
    questions,
    setQuestions,
    historicalQuestions,
    setHistoricalQuestions,
    databaseQuestions,
    setDatabaseQuestions,
    allQuestionsMap,
    translationMap,
    addQuestionsToState,
    updateQuestionInState,
    handleUpdateStatus,
    approvedCounts,
    approvedCount,

    pendingCount,
    totalApproved,
    overallPercentage,
    isTargetMet,
    maxBatchSize,
    deleteConfirmId,
    setDeleteConfirmId,
    showClearModal,
    setShowClearModal,
    handleDelete,
    confirmDelete,
    handleDeleteAllQuestions,
    checkAndStoreQuestions,
    unifiedQuestions,
  } = useQuestionManager(config, showMessage);

  // 2.5. Crash Recovery - detect and restore from cloud backup
  const {
    showRecoveryPrompt,
    recoveryData,
    isRecovering,
    handleRecover,
    dismissRecovery,
  } = useCrashRecovery(questions, addQuestionsToState, showMessage);

  // 3. Status State (Shared)
  const [status, setStatus] = useState("");

  // 4. File Handling
  const {
    _files,
    _setFiles,
    fileInputRef,
    _isDetecting,
    handleFileChange,
    _removeFile,
    getFileContext,
    handleDetectTopics,
  } = useFileHandler(
    config,
    setConfig,
    addQuestionsToState,
    showMessage,
    setStatus,
    isApiReady,
    effectiveApiKey
  );

  // 5. Filtering & Search (extracted to useFiltering hook)
  const {
    searchTerm,
    setSearchTerm,
    filterMode,
    setFilterMode,
    showHistory,
    setShowHistory,
    filterByCreator,
    setFilterByCreator,
    filterTags,
    setFilterTags,
    currentReviewIndex,
    setCurrentReviewIndex,
    sortBy,
    setSortBy,
    contextFilteredQuestions: _contextFilteredQuestions,
    contextCounts,
    filteredQuestions,
    uniqueFilteredQuestions,
  } = useFiltering({
    questions: unifiedQuestions,
    historicalQuestions: [], // We are using the unified list as source of truth
    config,
    appMode,
  });

  // 6. Generation & Translation Logic
  const {
    isGenerating,
    isProcessing,
    translationProgress,
    handleGenerate,
    handleTranslateSingle,
    handleExplain,
    handleVariate,
    handleCritique,
    handleApplyRewrite,
    handleBulkTranslateMissing,
  } = useGeneration(
    config,
    setConfig,
    effectiveApiKey,
    isApiReady,
    isTargetMet,
    maxBatchSize,
    getFileContext,
    checkAndStoreQuestions,
    addQuestionsToState,
    updateQuestionInState,
    handleLanguageSwitch,
    showMessage,
    setStatus,
    setShowNameModal,
    setShowApiError,
    setShowHistory,
    translationMap,
    allQuestionsMap
  );

  // 7. Modal State (extracted to useModalState hook)
  const {
    showExportMenu: _showExportMenu,
    setShowExportMenu,
    showBulkExportModal,
    setShowBulkExportModal,
    showAnalytics,
    setShowAnalytics,
    dataMenuOpen: _dataMenuOpen,
    setDataMenuOpen: _setDataMenuOpen,
    dataMenuRef: _dataMenuRef,
    showAdvancedConfig,
    setShowAdvancedConfig,
    showDangerZone,
    setShowDangerZone,
    showApiKeyModal,
    setShowApiKeyModal,
  } = useModalState();

  // 8. Export Logic (must come before Navigation since Navigation depends on handleLoadFromFirestore)
  const {
    handleExportToSheets,
    handleLoadFromSheets,
    handleLoadFromFirestore,
    handleBulkExport,
  } = useExport(
    config,
    questions,
    historicalQuestions,
    uniqueFilteredQuestions,
    allQuestionsMap,
    showHistory,
    showMessage,
    setStatus,
    () => {},
    setDatabaseQuestions,
    setAppMode,
    setShowExportMenu,
    setShowBulkExportModal,
    setHistoricalQuestions
  );

  // Auto-load database questions on startup for difficulty distribution chart
  const hasAutoLoadedRef = useRef(false);
  useEffect(() => {
    if (user && !authLoading && !hasAutoLoadedRef.current) {
      hasAutoLoadedRef.current = true;
      console.log("≡ƒôè Auto-loading database for difficulty chart...");
      handleLoadFromFirestore(true); // Silent auto-recovery
    }
  }, [user, authLoading, handleLoadFromFirestore]);

  // ONE-TIME MIGRATION: Fix auto-accepted questions in Firestore (inlined)
  const hasMigratedRef = useRef(false);
  useEffect(() => {
    const runMigration = async () => {
      const migrationKey = "ue5_migration_auto_accept_fix";
      if (localStorage.getItem(migrationKey) === "completed") return;

      if (user && !authLoading && !hasMigratedRef.current) {
        hasMigratedRef.current = true;
        try {
          console.log(
            "≡ƒöä Running migration: fixing auto-accepted questions..."
          );

          // Inline migration code (can't use dynamic import - not bundled by Vite)
          const { db, auth } = await import("./services/firebase");
          const { collection, getDocs, doc, updateDoc } = await import(
            "firebase/firestore"
          );

          const questionsRef = collection(db, "questions");
          const snapshot = await getDocs(questionsRef);

          let fixedCount = 0;
          const batch = [];

          snapshot.forEach((docSnap) => {
            const question = docSnap.data();
            if (question.status === "accepted" && !question.reviewCompletedAt) {
              batch.push(
                updateDoc(doc(db, "questions", docSnap.id), {
                  status: "pending",
                  migratedAt: new Date().toISOString(),
                  migrationReason: "auto-accept-bug-fix",
                })
              );
              fixedCount++;
            }
          });

          if (batch.length > 0) {
            await Promise.all(batch);
            console.log(
              `Γ£à Migration: Fixed ${fixedCount} of ${snapshot.size} questions`
            );
            showMessage(
              `Γ£à Fixed ${fixedCount} auto-accepted questions - now pending`,
              5000
            );
            setTimeout(() => handleLoadFromFirestore(), 1000);
          } else {
            console.log(
              `Γ£à No questions needed fixing (checked ${snapshot.size} questions)`
            );
          }

          localStorage.setItem(migrationKey, "completed");
        } catch (error) {
          console.error("Γ¥î Migration error:", error);
        }
      }
    };
    runMigration();
  }, [user, authLoading, showMessage, handleLoadFromFirestore]);

  // 9. Review Actions (bulk operations)
  const {
    handleClearPending,
    handleBulkAcceptHighScores,
    handleBulkCritiqueAll,
  } = useReviewActions({
    uniqueFilteredQuestions,
    setQuestions,
    handleUpdateStatus,
    handleCritique,
    showMessage,
  });

  // 10. Database Actions
  const { handleUpdateDatabaseQuestion, handleKickBackToReview } =
    useDatabaseActions({
      setDatabaseQuestions,
      setHistoricalQuestions,
      showMessage,
    });

  // 11. Navigation (depends on handleLoadFromFirestore from useExport)
  const { handleModeSelect, handleViewDatabase, handleGoHome } = useNavigation({
    setAppMode,
    setShowExportMenu,
    setShowHistory,
    setFilterMode,
    handleLoadFromFirestore,
  });

  // Bulk selection (extracted to useBulkSelection hook)
  const {
    selectedIds,
    toggleSelection,
    clearSelection,
    selectAll,
    bulkUpdateStatus,
  } = useBulkSelection({
    items: uniqueFilteredQuestions,
    handleUpdateStatus,
    showMessage,
  });

  // Keyboard Shortcuts (extracted to useKeyboardShortcuts hook)
  useKeyboardShortcuts({
    appMode,
    isGenerating,
    isTargetMet,
    isApiReady,
    maxBatchSize,
    handleGenerate,
    config,
    handleExportToSheets,
    handleBulkExport,
    setShowBulkExportModal,
    uniqueFilteredQuestionsLength: uniqueFilteredQuestions.length,
    setCurrentReviewIndex,
    isAdmin, // Only admins can use export shortcuts (Ctrl+S, Ctrl+E)
  });

  // App Handlers (extracted to useAppHandlers hook)
  const { handleManualUpdate, handleSelectCategory, handleSaveApiKey } =
    useAppHandlers({
      updateQuestionInState,
      setConfig,
      handleChange,
      setShowApiKeyModal,
    });

  // Render - Loading state
  if (authLoading || registrationLoading) {
    return <LoadingSpinner />;
  }

  // Render - Not authenticated
  if (!user) {
    // Check if there's an invite code in URL - show invite signup
    const inviteCode = getInviteFromUrl();
    if (inviteCode) {
      return (
        <InviteSignUp
          onSuccess={(role) => {
            markAsRegistered(role);
          }}
        />
      );
    }
    return <SignIn />;
  }

  // User is authenticated - proceed to app (no registration check needed)

  if (appMode === "landing") {
    return (
      <>
        <LandingPage
          onSelectMode={handleModeSelect}
          apiKeyStatus={apiKeyStatus}
          isCloudReady={isAuthReady}
          onOpenSettings={() => {
            console.log("≡ƒÜÇ Configure Now clicked!");
            setShowApiKeyModal(true);
          }}
          isAdmin={isAdmin} // Pass admin status
          onStartTutorial={() => handleStartTutorial("welcome")} // Start welcome tour
        />
        {/* API Key Modal for Configure Now button */}
        <ApiKeyModal
          isOpen={showApiKeyModal}
          onClose={() => setShowApiKeyModal(false)}
          onSave={handleSaveApiKey}
          currentKey={config.apiKey}
        />
      </>
    );
  }

  return (
    <div className="flex flex-col h-screen bg-slate-950 font-sans text-slate-200">
      {/* Crash Recovery Prompt - highest priority */}
      <CrashRecoveryPrompt
        isOpen={showRecoveryPrompt}
        recoveryData={recoveryData}
        isRecovering={isRecovering}
        onRecover={handleRecover}
        onDismiss={dismissRecovery}
      />
      <GlobalModals
        visibility={{
          showNameModal,
          showClearModal,
          showBulkExportModal,
          showSettings,
          showAnalytics,
          showDangerZone,
          showApiKeyModal,
          showTerms,
          showAgeGate,
          tutorialActive,
          deleteConfirmId,
          showAdvancedConfig,
          showApiKey,
        }}
        state={{
          config,
          isProcessing,
          status,
          translationProgress,
          allQuestionsMap,
          appMode,
          currentStep,
          tutorialSteps,
          metrics: {
            totalApproved: approvedCount,
            totalQuestions: questions.length,
          },
          isApiReady,
          customTags,
          isAdmin,
        }}
        handlers={{
          handleNameSave,
          handleDeleteAllQuestions,
          handleBulkExport,
          confirmDelete,
          setDeleteConfirmId,
          onCloseBulkExport: () => setShowBulkExportModal(false),
          onCloseSettings: () => setShowSettings(false),
          onCloseAnalytics: () => setShowAnalytics(false),
          onCloseDangerZone: () => setShowDangerZone(false),
          onCloseApiKey: () => setShowApiKeyModal(false),
          handleChange,
          handleSaveApiKey,
          setShowTerms,
          setTermsAccepted,
          setShowAgeGate,
          setShowClearModal,
          handleTutorialNext,
          handleTutorialPrev,
          handleTutorialSkip,
          handleTutorialComplete,
          onResetSettings: () =>
            setConfig({ ...config, ...useAppConfig.defaultConfig }),
          onHardReset: () => {
            localStorage.clear();
            window.location.reload();
          },
          fileInputRef,
          handleFileChange,
          setShowAdvancedConfig,
          setShowApiKey,
          handleDetectTopics,
          onSaveCustomTags: handleSaveCustomTags,
          window: window,
        }}
      />
      <Header
        apiKeyStatus={apiKeyStatus}
        isCloudReady={isAuthReady}
        onHome={handleGoHome}
        creatorName={config.creatorName}
        appMode={appMode}
        tokenUsage={tokenUsage}
        onRestartTutorial={handleRestartTutorial}
        onStartTutorial={handleStartTutorial}
        isAdmin={isAdmin}
      />

      <MainLayout
        appMode={appMode}
        setAppMode={setAppMode}
        effectiveApiKey={effectiveApiKey}
        isAdmin={isAdmin}
        sidebarProps={{
          showGenSettings,
          setShowGenSettings,
          config,
          handleChange,
          allQuestionsMap,
          approvedCounts,
          overallPercentage,
          totalApproved,
          isTargetMet,
          maxBatchSize,
          batchSizeWarning,
          handleGenerate,
          isGenerating,
          isApiReady,
          handleBulkTranslateMissing,
          isProcessing,
          setShowSettings,
          handleSelectCategory,
          customTags,
          status,
          showMessage,
          isAdmin,
        }}
        handleModeSelect={handleModeSelect}
        handleViewDatabase={handleViewDatabase}
        pendingCount={pendingCount}
        toolbarProps={{
          mode: appMode,
          counts: contextCounts,
          filterMode,
          setFilterMode,
          filterByCreator,
          setFilterByCreator,
          filterTags,
          setFilterTags,
          customTags,
          searchTerm,
          setSearchTerm,
          sortBy,
          setSortBy,
          isProcessing,
          status,
          isAuthReady,
          config,
          onLoadSheets: handleLoadFromSheets,
          onLoadFirestore: handleLoadFromFirestore,
          onBulkExport: () => setShowBulkExportModal(true),
          onClearPending: handleClearPending,
          onBulkAcceptHighScores:
            appMode === "review" ? handleBulkAcceptHighScores : undefined,
          onBulkCritiqueAll:
            appMode === "review" ? handleBulkCritiqueAll : undefined,
        }}
        showHistory={showHistory}
        uniqueFilteredQuestions={uniqueFilteredQuestions}
        questions={questions}
        status={status}
        databaseQuestions={databaseQuestions}
        config={config}
        isProcessing={isProcessing}
        allQuestionsMap={allQuestionsMap}
        viewRouterHandlers={{
          handleLoadFromSheets,
          handleLoadFromFirestore,
          handleUpdateDatabaseQuestion,
          handleKickBackToReview,
          handleUpdateStatus,
          handleExplain,
          handleVariate,
          handleCritique,
          handleApplyRewrite,
          handleTranslateSingle,
          handleLanguageSwitch,
          handleDelete,
          handleManualUpdate,
          selectAll,
          clearSelection,
          bulkUpdateStatus,
          toggleSelection,
        }}
        viewRouterState={{
          currentReviewIndex,
          selectedIds,
          translationMap,
          filterByCreator,
          filteredQuestions,
          questions,
          status,
          filterMode,
          sortBy,
          showHistory,
        }}
        viewRouterSetters={{
          setDatabaseQuestions,
          setCurrentReviewIndex,
          setFilterByCreator,
          showMessage,
        }}
        handleGoHome={handleGoHome}
        onStartTutorial={handleStartTutorial}
      />

      {/* API Key Modal - Simple popup for Configure Now button */}

      {/* Footer */}
      <Footer />

      {/* TOAST NOTIFICATIONS */}
      <ToastContainer toasts={toasts} onRemove={removeToast} />

      {/* TUTORIAL OVERLAY */}

      {/* COMPLIANCE MODALS */}
    </div>
  );
};

export default App;
// Force rebuild

import Icon from "./Icon";

import GenerationSettings from "./sidebar/GenerationSettings";
import CustomRules from "./sidebar/CustomRules";
import ProgressStats from "./sidebar/ProgressStats";
import BatchSizeControl from "./sidebar/BatchSizeControl";
import ActionFooter from "./sidebar/ActionFooter";
import TokenUsageDisplay from "./TokenUsageDisplay";

const Sidebar = ({
  showGenSettings,
  setShowGenSettings,
  config,
  handleChange,
  allQuestionsMap,
  approvedCounts,
  overallPercentage,
  totalApproved,
  TARGET_TOTAL,
  TARGET_PER_CATEGORY,
  isTargetMet,
  maxBatchSize,
  batchSizeWarning,
  handleGenerate,
  isGenerating,
  isApiReady,
  handleBulkTranslateMissing,
  isProcessing,
  setShowSettings,
  handleSelectCategory,
  customTags = {},
  status = "", // Live generation status text
  showMessage,
  isAdmin, // Add isAdmin prop
}) => {
  return (
    <aside className="w-80 flex-shrink-0 z-10 shadow-xl border-r border-slate-700 bg-slate-950 p-6 overflow-y-auto flex flex-col gap-6">
      {isAdmin && (
        <>
          <div data-tour="generation-settings">
            <GenerationSettings
              config={config}
              handleChange={handleChange}
              customTags={customTags}
              isOpen={showGenSettings}
              onToggle={() => setShowGenSettings(!showGenSettings)}
              allQuestionsMap={allQuestionsMap}
              showMessage={showMessage}
              setShowGenSettings={setShowGenSettings}
            />
          </div>

          {/* Generate Button - Right after settings/chart */}
          <ActionFooter
            handleGenerate={handleGenerate}
            isGenerating={isGenerating}
            isTargetMet={isTargetMet}
            maxBatchSize={maxBatchSize}
            isApiReady={isApiReady}
            handleBulkTranslateMissing={handleBulkTranslateMissing}
            isProcessing={isProcessing}
            allQuestionsMap={allQuestionsMap}
            status={status}
          />
        </>
      )}

      {!isAdmin && (
        <div className="p-4 bg-slate-900 rounded-lg border border-slate-800 text-center">
          <Icon
            name="shield"
            className="mx-auto mb-2 text-slate-500"
            size={24}
          />
          <p className="text-sm text-slate-400">
            Generation features are restricted to administrators.
          </p>
        </div>
      )}

      <ProgressStats
        allQuestionsMap={allQuestionsMap}
        totalApproved={totalApproved}
        TARGET_TOTAL={TARGET_TOTAL}
        overallPercentage={overallPercentage}
      />

      <BatchSizeControl
        maxBatchSize={maxBatchSize}
        config={config}
        handleChange={handleChange}
        batchSizeWarning={batchSizeWarning}
      />

      {/* Token Usage Display */}
      <div className="mt-4 pt-4 border-t border-slate-800">
        <TokenUsageDisplay showDetailed={true} />
      </div>

      {/* Custom Rules - At the bottom */}
      {isAdmin && <CustomRules config={config} handleChange={handleChange} />}

      <div className="mt-4 pt-4 border-slate-800">
        <button
          onClick={() => setShowSettings(true)}
          data-tour="open-settings"
          className="w-full py-2 px-4 bg-slate-800 hover:bg-slate-700 text-slate-400 hover:text-white rounded flex items-center justify-center gap-2 transition-colors text-xs font-bold uppercase tracking-wider"
        >
          <Icon name="settings" size={14} /> Open Settings
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

/**
 * Quota Enforcement Utilities
 * Prevents generation when category/discipline quotas are met
 */

import { TARGET_PER_CATEGORY, TARGET_TOTAL, CATEGORY_KEYS } from "./constants";

/**
 * Calculates current question counts by category
 * @param {Array} questions - All questions
 * @returns {Object} Category counts
 */
export const getCategoryCounts = (questions) => {
  const counts = {};

  CATEGORY_KEYS.forEach((cat) => {
    counts[cat] = questions.filter(
      (q) => q.difficulty === cat && q.status !== "rejected"
    ).length;
  });

  return counts;
};

/**
 * Calculates counts by discipline and difficulty
 * @param {Array} questions - All questions
 * @returns {Object} Nested counts { discipline: { difficulty: count } }
 */
export const getDisciplineCounts = (questions) => {
  const counts = {};

  questions.forEach((q) => {
    if (q.status === "rejected") return;

    const discipline = q.discipline || "Unknown";
    const difficulty = q.difficulty || "Unknown";

    if (!counts[discipline]) counts[discipline] = {};
    if (!counts[discipline][difficulty]) counts[discipline][difficulty] = 0;

    counts[discipline][difficulty]++;
  });

  return counts;
};

/**
 * Checks if a category has reached its quota
 * @param {string} category - Category key (e.g., "Easy MC")
 * @param {Array} questions - All questions
 * @returns {boolean} True if quota met or exceeded
 */
export const isCategoryFull = (category, questions) => {
  const count = questions.filter(
    (q) => q.difficulty === category && q.status !== "rejected"
  ).length;

  return count >= TARGET_PER_CATEGORY;
};

/**
 * Checks if specific discipline+difficulty combo is full
 * @param {string} discipline - Discipline (e.g., "Blueprints")
 * @param {string} difficulty - Difficulty (e.g., "Easy MC")
 * @param {Array} questions - All questions
 * @returns {boolean} True if quota met
 */
export const isDisciplineFull = (discipline, difficulty, questions) => {
  const count = questions.filter(
    (q) =>
      q.discipline === discipline &&
      q.difficulty === difficulty &&
      q.status !== "rejected"
  ).length;

  return count >= TARGET_PER_CATEGORY;
};

/**
 * Checks if total question count has been reached
 * @param {Array} questions - All questions
 * @returns {boolean} True if total quota met
 */
export const isTotalQuotaMet = (questions) => {
  const count = questions.filter((q) => q.status !== "rejected").length;
  return count >= TARGET_TOTAL;
};

/**
 * Gets remaining quota for a specific category
 * @param {string} category - Category key
 * @param {Array} questions - All questions
 * @returns {number} Remaining questions allowed (0 if full)
 */
export const getRemainingQuota = (category, questions) => {
  const current = questions.filter(
    (q) => q.difficulty === category && q.status !== "rejected"
  ).length;

  return Math.max(0, TARGET_PER_CATEGORY - current);
};

/**
 * Gets quota status for all categories
 * @param {Array} questions - All questions
 * @returns {Object} { category: { current, target, remaining, isFull } }
 */
export const getQuotaStatus = (questions) => {
  const status = {};

  CATEGORY_KEYS.forEach((cat) => {
    const current = questions.filter(
      (q) => q.difficulty === cat && q.status !== "rejected"
    ).length;

    status[cat] = {
      current,
      target: TARGET_PER_CATEGORY,
      remaining: Math.max(0, TARGET_PER_CATEGORY - current),
      isFull: current >= TARGET_PER_CATEGORY,
      percentage: Math.round((current / TARGET_PER_CATEGORY) * 100),
    };
  });

  // Add total
  const totalCurrent = questions.filter((q) => q.status !== "rejected").length;
  status.TOTAL = {
    current: totalCurrent,
    target: TARGET_TOTAL,
    remaining: Math.max(0, TARGET_TOTAL - totalCurrent),
    isFull: totalCurrent >= TARGET_TOTAL,
    percentage: Math.round((totalCurrent / TARGET_TOTAL) * 100),
  };

  return status;
};

/**
 * Validates if generation should be allowed
 * @param {string} discipline - Selected discipline
 * @param {string} difficulty - Selected difficulty
 * @param {number} batchSize - Number of questions to generate
 * @param {Array} questions - All existing questions
 * @param {string} type - Selected type (MC or T/F)
 * @returns {Object} { allowed: boolean, reason: string, maxAllowed: number, forceType: string }
 */
export const validateGeneration = (
  discipline,
  difficulty,
  batchSize,
  questions,
  type = "Multiple Choice"
) => {
  // Helper to normalize difficulty from "Easy MC" -> "Easy"
  const normalizeDiff = (d) => {
    if (!d) return d;
    const base = d.split(" ")[0];
    // Map config values to base difficulty
    if (base === "Beginner") return "Easy";
    if (base === "Intermediate") return "Medium";
    if (base === "Expert") return "Hard";
    return base;
  };

  const targetDiff = normalizeDiff(difficulty);

  // Check total quota - WARN only, don't block
  // Individual category quotas (below) control actual blocking
  // This prevents blocking generation for unfilled categories when others are full
  const totalQuotaMet = isTotalQuotaMet(questions);
  const warnAboutTotal = totalQuotaMet;

  // Filter questions for this discipline and base difficulty
  const relevantQuestions = questions.filter((q) => {
    if (q.status === "rejected") return false;
    if (q.discipline !== discipline) return false;
    const qDiff = normalizeDiff(q.difficulty);
    return qDiff === targetDiff;
  });

  // Count MC and T/F separately
  const mcCount = relevantQuestions.filter(
    (q) => q.type === "Multiple Choice" || q.type === "MC"
  ).length;

  const tfCount = relevantQuestions.filter(
    (q) => q.type === "True/False" || q.type === "T/F"
  ).length;

  const MC_QUOTA = TARGET_PER_CATEGORY;
  const TF_QUOTA = TARGET_PER_CATEGORY;

  // Check if both MC and T/F are full for this difficulty
  if (mcCount >= MC_QUOTA && tfCount >= TF_QUOTA) {
    return {
      allowed: false,
      reason: `Both MC (${mcCount}/${MC_QUOTA}) and T/F (${tfCount}/${TF_QUOTA}) are full for ${difficulty}. Select a different difficulty.`,
      maxAllowed: 0,
    };
  }

  // For specific type selection
  if (type === "Multiple Choice" || type === "MC") {
    if (mcCount >= MC_QUOTA) {
      return {
        allowed: false,
        reason: `MC quota full for ${difficulty} (${mcCount}/${MC_QUOTA}). Switch to T/F.`,
        maxAllowed: 0,
        forceType: "True/False",
      };
    }
    return {
      allowed: true,
      reason: "Generation allowed",
      maxAllowed: Math.min(batchSize, MC_QUOTA - mcCount),
    };
  }

  if (type === "True/False" || type === "T/F") {
    if (tfCount >= TF_QUOTA) {
      return {
        allowed: false,
        reason: `T/F quota full for ${difficulty} (${tfCount}/${TF_QUOTA}). Switch to MC.`,
        maxAllowed: 0,
        forceType: "Multiple Choice",
      };
    }
    return {
      allowed: true,
      reason: "Generation allowed",
      maxAllowed: Math.min(batchSize, TF_QUOTA - tfCount),
    };
  }

  // Default: allow generation
  const totalRemaining = MC_QUOTA - mcCount + (TF_QUOTA - tfCount);
  return {
    allowed: true,
    reason: "Generation allowed",
    maxAllowed: Math.min(batchSize, totalRemaining),
  };
};

/**
 * localStorage wrapper (encryption removed - API key now server-side)
 * 
 * Simple JSON storage - no encryption needed since all sensitive operations
 * (Gemini API calls) go through Cloud Functions.
 */

/**
 * Store item in localStorage
 */
export const setSecureItem = (key, value) => {
    try {
        localStorage.setItem(key, JSON.stringify(value));
    } catch (err) {
        console.error(`Failed to store ${key}:`, err);
    }
};

/**
 * Retrieve item from localStorage
 */
export const getSecureItem = (key) => {
    try {
        const stored = localStorage.getItem(key);
        if (!stored) return null;
        return JSON.parse(stored);
    } catch (err) {
        console.warn(`Could not parse ${key}, returning null`);
        return null;
    }
};
